package com.tencent.weknora.knowledge;
import static org.assertj.core.api.Assertions.*;
import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.*;import java.nio.file.*;import java.time.*;import java.util.*;import java.util.concurrent.atomic.AtomicInteger;import java.util.stream.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;

/** Actual Go RequestKnowledgeBaseProfileRefresh and Asynq options/duplicate behavior. */
class KnowledgeBaseProfileEnqueueGoParityTest {
 @TempDir Path temp;final ObjectMapper json=new ObjectMapper();
 static {try{com.tencent.weknora.retrieval.NativeDatabaseRuntime.initialize();}catch(java.sql.SQLException e){throw new ExceptionInInitializerError(e);}}
 @TestFactory Stream<DynamicTest> actualGoProfileProducer()throws Exception{JsonNode cases;try(var in=getClass().getResourceAsStream("/go-knowledge-base-profile-enqueue.json")){cases=json.readTree(in);}assertThat(cases.size()).isEqualTo(12);var sequence=new AtomicInteger();return StreamSupport.stream(cases.spliterator(),false).map(row->DynamicTest.dynamicTest(row.path("name").asText(),()->compare(row,sequence.incrementAndGet())));}
 void compare(JsonNode oracle,int no)throws Exception{var f=new DocumentProcessingCompatibilityTest();f.temp=temp;f.database(no,false);var handler=new KnowledgeBaseProfileHandler(null,json,null,null,f.tasks,Clock.fixed(Instant.parse("2026-10-15T00:00:01Z"),ZoneOffset.UTC));String name=oracle.path("name").asText();if(name.equals("failure"))f.jdbc.execute("CREATE TRIGGER reject_profile BEFORE INSERT ON java_task_jobs WHEN NEW.type='kb:profile' BEGIN SELECT RAISE(ABORT,'synthetic profile enqueue failure'); END");boolean queued=handler.enqueue(1,oracle.path("base"),oracle.path("force").asBoolean(),json.createObjectNode().put("language",oracle.path("language").asText()));if(Set.of("duplicate","force-twice").contains(name))queued=handler.enqueue(1,oracle.path("base"),oracle.path("force").asBoolean(),json.createObjectNode().put("language",oracle.path("language").asText()));assertThat(queued).isEqualTo(!oracle.path("tasks").isEmpty());var actual=json.createArrayNode();for(var job:f.tasks.list(1,20)){var row=json.createObjectNode().put("type",job.type()).put("queue",job.queue()).put("max_retry",job.maxAttempts()-1).put("timeout",job.timeoutMillis()).put("scheduled",job.availableAt()>job.createdAt()).put("debounced_id",job.idempotencyKey().startsWith("kb-profile:"));row.set("payload",job.payload());actual.add(row);assertThat(job.availableAt()-job.createdAt()).isEqualTo(oracle.path("force").asBoolean()?0:30000);}assertThat(json.readTree(actual.toString())).isEqualTo(oracle.path("tasks"));}
 @Test void subsequentWindowQueuesFreshTaskAndWrongOwnerNeverQueues()throws Exception{var f=new DocumentProcessingCompatibilityTest();f.temp=temp;f.database(90,false);var base=f.knowledge.knowledgeBase(1,"kb");base.set("profile_config",json.createObjectNode().put("enabled",true));var source=json.createObjectNode().put("language","en-US");var initial=new KnowledgeBaseProfileHandler(null,json,null,null,f.tasks,Clock.fixed(Instant.ofEpochSecond(300),ZoneOffset.UTC));assertThat(initial.enqueue(2,base,false,source)).isFalse();assertThat(initial.enqueue(1,base,false,source)).isTrue();assertThat(initial.enqueue(1,base,false,source)).isTrue();assertThat(f.tasks.list(1,20)).hasSize(1);var next=new KnowledgeBaseProfileHandler(null,json,null,null,f.tasks,Clock.fixed(Instant.ofEpochSecond(330),ZoneOffset.UTC));assertThat(next.enqueue(1,base,false,source)).isTrue();assertThat(f.tasks.list(1,20)).hasSize(2);}
}
